import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims, useCounts } from '../claims/claims';
import { GRADES, usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useFloor } from '../settings/settings';
import { NA, PERCENT, claimDueCents, ratesKey, setRate, show, useGradeRate, usePersonRate, useRates } from './rates';
import type { RateInput } from './rates';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: RateInput = { grade: 'A', rate: '', from: '' };

// The sheet's rates: a form that sets a grade's rate from a from-date (none: from the beginning of
// time), replacing any rate it had for that from-date; each grade's rate in force on the sheet's today
// (n/a when none applies); and every rate set, by grade then from-date.
function Rates() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const rateOf = useGradeRate();
  const rates = useRates().data ?? [];
  const [form, setForm] = useState<RateInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: RateInput) => setRate(sheet!, user, input),
    onSuccess: async () => {
      setForm((f) => ({ ...f, rate: '', from: '' }));
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet!) });
    },
    onError: () =>
      setError('The rate could not be set: it must be a percent of 0.00 or more, with up to two decimals, and a date if from is given.'),
  });

  if (!sheet) return null;

  const change = (patch: Partial<RateInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!PERCENT.test(form.rate.trim())) {
      setError('The rate must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = form.from.trim();
    if (from !== '' && !DATE.test(from)) {
      setError('The from-date must be a date (yyyy-mm-dd).');
      return;
    }
    once(() => save.mutateAsync({ grade: form.grade, rate: form.rate.trim(), from }));
  };

  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <form data-testid="rate-form" onSubmit={submit}>
        <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
          {GRADES.map((g) => (
        </select>
          data-testid="rate-form-pct"
          inputMode="decimal"
          data-testid="rate-form-from"
          type="date"
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && <span data-testid="rate-form-error">{error}</span>}
      </form>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOf(g) ?? NA}</td>
            </tr>
        </tbody>
      </table>
      <table data-testid="rate-history">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
        </tbody>
      </table>
    </section>
}

function DueColumn() {
  return <th>Due</th>;
}

/** A person's due-total in cents: the already-rounded figures of their claims that count added up
 *  (0 when none counts). Undefined for n/a: their grade has no rate today and no settled claim keeps
 *  a figure. */
function useDueTotal() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const floor = useFloor();
  return (personId: number) => {
    const figures = claims
      .filter((c) => c.personId === personId && counts(c))
      .map((c) => ({ claim: c, due: claimDueCents(c, rateOf(personId, c.date), floor) }));
    const kept = figures.some((f) => f.claim.status === 'SETTLED' && f.due !== undefined);
    if (rateOf(personId) === undefined && !kept) return undefined;
    return figures.reduce((n, f) => n + (f.due ?? 0n), 0n);
  };
}

// A person's due-total: n/a when their grade has no rate today, unless a settled claim keeps a figure.
function PersonDueTotal({ personId }: { personId: number }) {
  const due = useDueTotal()(personId);
  return <td data-testid="person-due-total">{due === undefined ? NA : show(due)}</td>;
}

// The sheet's due-total: everyone's due-total added up, skipping n/a.
function DueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const dueOf = useDueTotal();
  if (!sheet) return null;
  const sum = people.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n);
  return (
    <section data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{show(sum)}</strong>
    </section>
}

export const contributions = [
  HomeMain.fill({ order: 5, Component: Rates }),
  PersonColumns.fill({ order: 20, Component: DueColumn }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  HomeMain.fill({ order: 21, Component: DueTotal }),
];
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { useClaims, useCounts } from '../claims/claims';
import { claimDueCents, hundredths, show, usePersonRate } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useFloor } from '../settings/settings';
import { addPeriod, closePeriod, periodsKey, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

/** A period's due-total in cents: once closed, the one fixed then; otherwise the due of the claims that
 *  count whose date falls in it (n/a as 0). */
function usePeriodDue() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  const counts = useCounts();
  const floor = useFloor();
  return (period: Period) =>
    period.closed && period.closedTotal !== null
      ? hundredths(period.closedTotal)
      : claims
      .filter((c) => counts(c) && period.from <= c.date && c.date <= period.to)
      .reduce((n, c) => n + (claimDueCents(c, rateOf(c.personId, c.date), floor) ?? 0n), 0n);
}

// The sheet's periods: a form that adds one (a name unique on the sheet, from on or before to, not
// overlapping another), and each period with its dates, its due-total, whether it is closed and a button
// that closes it. A refused close shows on its period.
function Periods() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const periods = usePeriods().data ?? [];
  const dueOf = usePeriodDue();
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();
  const [periodErrors, setPeriodErrors] = useState<Record<string, string>>({});

  const close = useMutation({
    mutationFn: (name: string) => closePeriod(sheet!, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) }),
    onError: async (_e, name) => {
      setPeriodErrors((e) => ({ ...e, [name]: `The period ${name} could not be closed.` }));
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  const take = (period: Period) => {
    setPeriodErrors(({ [period.name]: _, ...rest }) => rest);
    if (period.closed) {
      setPeriodErrors((e) => ({ ...e, [period.name]: `The period ${period.name} is already closed.` }));
      return;
    }
    close.mutate(period.name);
  };

  const save = useMutation({
    mutationFn: (input: PeriodInput) => addPeriod(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
    onError: async () => {
      setError('The period could not be added: its name must be new on the sheet and its dates must not overlap another period.');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet!) });
    },
  });

  if (!sheet) return null;

  const change = (patch: Partial<PeriodInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.name.trim();
    const from = form.from.trim();
    const to = form.to.trim();
    if (name === '') {
      setError('The period must have a name.');
      return;
    }
    if (!DATE.test(from) || !DATE.test(to)) {
      setError('The from and to dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (to < from) {
      setError('The to-date must be on or after the from-date.');
      return;
    }
    if (periods.some((p) => p.name === name)) {
      setError(`A period named ${name} is already on the sheet.`);
      return;
    }
    const clash = periods.find((p) => p.from <= to && from <= p.to);
    if (clash) {
      setError(`The period overlaps ${clash.name}.`);
      return;
    }
    once(() => save.mutateAsync({ name, from, to }));
  };

  return (
    <section data-testid="periods">
      <h2>Periods</h2>
      <form data-testid="period-form" onSubmit={submit}>
          data-testid="period-form-name"
          data-testid="period-form-from"
          type="date"
          data-testid="period-form-to"
          type="date"
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {error && <span data-testid="period-form-error">{error}</span>}
      </form>
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{show(dueOf(p))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                <button type="button" data-testid="period-close" onClick={() => take(p)}>
                  Close
                </button>
                {periodErrors[p.name] && <span data-testid="period-error">{periodErrors[p.name]}</span>}
              </td>
            </tr>
        </tbody>
      </table>
    </section>
}

export const contributions = [HomeMain.fill({ order: 6, Component: Periods })];
